html = {s: (p/s).read_text().split('?>', 1)[1] for s in ['public/index.php', 'public/admin/add.php']}
changed = set()
def put(name, content):
    f = p/name
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_text(content, encoding='utf-8')
    changed.add(name)
def replace(name, old, new):
    text = (p/name).read_text(encoding='utf-8')
    if text.count(old) != 1:
        raise RuntimeError('Unexpected source: ' + name + ' / ' + old)
    put(name, text.replace(old, new, 1))
